static z_t1231_t z_t1231_copy(const z_t1231_t* _this) {
    z_t1231_t _out = {0};
    if (!_this || _this->length == 0) return _out;
    _out.length = _this->length;
    _out.capacity = _this->length;
    _out.data = (uint32_t*)z_xcalloc(_this->length, sizeof(uint32_t));
    memcpy(_out.data, _this->data, (size_t)_this->length * sizeof(uint32_t));
    return _out;
}

